// Generated by LCD Wizard - touch panel: FT3168 / FT6146 (I2C)

#include <Arduino.h>
#include <lvgl.h>
#include "lcd_pins.h"
#include "touch.h"

// ---- touch: FT3168 / FT6146 ----
#include <Wire.h>

// A touch controller can stop answering - interrupted mid-transfer by a
// reboot, browned out, or wedged - and it keeps that state until it is
// reset, because a reboot of the MCU does not power it down. So it is reset
// and its bus freed on every boot, and again whenever it goes quiet.
static void touch_reset_pulse(void)
{
    if (TOUCH_RST < 0) return;
    pinMode(TOUCH_RST, OUTPUT);
    digitalWrite(TOUCH_RST, LOW);  delay(20);
    digitalWrite(TOUCH_RST, HIGH); delay(300);
}

static bool touch_present(void)
{
    Wire.beginTransmission(TOUCH_I2C_ADDR);
    return Wire.endTransmission() == 0;
}

static void touch_start(void)
{
    touch_reset_pulse();
    // Wire is shared with other devices here, so it is left running.
    Wire.begin(TOUCH_SDA, TOUCH_SCL, TOUCH_I2C_FREQ);
    Wire.setTimeout(5);   // the Stream timeout: a refused read is not waited for
    if (TOUCH_INT >= 0) pinMode(TOUCH_INT, INPUT);
}

void touch_hw_init(void)
{
    touch_start();
    if (touch_present()) Serial.printf("touch: FT3168 / FT6146 answering at 0x%02X\n", TOUCH_I2C_ADDR);
    else Serial.printf("touch: nothing answering at 0x%02X - check SDA, SCL, the address and RESET\n", TOUCH_I2C_ADDR);
}

// Bus errors in a row - "no finger" is a successful read, so this counts
// only a controller that has stopped answering.
static uint16_t touch_fail_run = 0;

static bool i2c_read_regs(uint16_t reg, uint8_t *buf, uint8_t len, bool reg16)
{
    Wire.beginTransmission(TOUCH_I2C_ADDR);
    if (reg16) Wire.write((uint8_t)(reg >> 8));
    Wire.write((uint8_t)(reg & 0xFF));
    bool ok = Wire.endTransmission(false) == 0 &&
              Wire.requestFrom((int)TOUCH_I2C_ADDR, (int)len) == len;
    if (!ok) {
        if (touch_fail_run < 0xFFFF) touch_fail_run++;
        return false;
    }
    for (uint8_t i = 0; i < len; i++) buf[i] = Wire.read();
    touch_fail_run = 0;
    return true;
}

// Called from every read: after ~20 failed reads in a row (about half a
// second) the controller is reset and the bus restarted, at most every 3 s.
static void touch_watchdog(void)
{
    static uint32_t last_reset = 0;
    static uint16_t resets = 0;
    if (touch_fail_run < 20 || millis() - last_reset < 3000) return;
    last_reset = millis();
    resets++;
    Serial.printf("touch: controller stopped answering - resetting it (%u)\n", resets);
    touch_start();
    touch_fail_run = touch_present() ? 0 : 20;
    Serial.println(touch_fail_run ? "touch: still not answering" : "touch: back");
}

static bool touch_read_raw(uint16_t *x, uint16_t *y)
{
    touch_watchdog();
    uint8_t p[5];
    if (!i2c_read_regs(0x02, p, 5, false)) return false;
    if ((p[0] & 0x0F) == 0) return false;
    *x = (uint16_t)((p[1] & 0x0F) << 8) | p[2];
    *y = (uint16_t)((p[3] & 0x0F) << 8) | p[4];
    return true;
}

static void touch_to_screen(int32_t *px, int32_t *py)
{
    int32_t x = *px, y = *py;
    // How the touch panel is bonded to the glass, in the panel's own
    // axes - a physical fact, independent of any rotation below.
    #if TOUCH_SWAP_XY
    { int32_t t = x; x = y; y = t; }
    #endif
    #if TOUCH_INVERT_X
    x = (LCD_H_RES - 1) - x;
    #endif
    #if TOUCH_INVERT_Y
    y = (LCD_V_RES - 1) - y;
    #endif

    // The software rotation, so a press follows what setRotation() did to
    // the picture. Without this the display turns and the touch does not.
    #if LCD_ROTATION == 1
    { int32_t t = x; x = y; y = (LCD_H_RES - 1) - t; }
    #elif LCD_ROTATION == 2
    x = (LCD_H_RES - 1) - x;
    y = (LCD_V_RES - 1) - y;
    #elif LCD_ROTATION == 3
    { int32_t t = y; y = x; x = (LCD_V_RES - 1) - t; }
    #endif
    *px = x;
    *py = y;
}

// ---- LVGL input device ----
static void touch_read(lv_indev_t *indev, lv_indev_data_t *data)
{
    uint16_t x, y;
    if (!touch_read_raw(&x, &y)) {
        data->state = LV_INDEV_STATE_RELEASED;
        return;
    }
    int32_t sx = x, sy = y;
    touch_to_screen(&sx, &sy);
    data->point.x = sx;
    data->point.y = sy;
    data->state = LV_INDEV_STATE_PRESSED;
}

void touch_lvgl_init(void)
{
    lv_indev_t *indev = lv_indev_create();
    lv_indev_set_type(indev, LV_INDEV_TYPE_POINTER);
    lv_indev_set_read_cb(indev, touch_read);
}
